form.script:
$("input.o_field_number ").on("click", function() {
    $(this).select();
});
$("input.o_field_number ").on("change", function() {
    var value = $(this).val()
    if(value != '' && String(parseFloat(value)) != 'NaN'){
        $(this).val(parseFloat(value));
    }
});
$(document).ready(function(){
    setWidthTotals()
    $('.sales_forecast_page').click(function(){
        setTimeout(function(){
            setWidthTotals()
        })
    })
    $('.profit_and_loss_page').click(function(){
        setTimeout(function(){
            setWidthTotals()
        })
    })
    $('.cash_flow_page').click(function(){
        setTimeout(function(){
            setWidthTotals()
        })
    })
    $('.productivity_ratio_page').click(function(){
        setTimeout(function(){
            setWidthTotals()
        })
    })
    function setWidthTotals(){
        if(window.innerWidth < 1000){
            $('.total_revenue_td').addClass('d-none')
        }
        $('[name="sales_forecast_lines"] .table-responsive').on('scroll', function() {
            $('.forecast_totals').scrollLeft($(this).scrollLeft());
        });
        $('.forecast_totals').on('scroll', function() {
            $('[name="sales_forecast_lines"] .table-responsive').scrollLeft($(this).scrollLeft());
        });
        $('[name="profit_loss_lines"] .table-responsive').on('scroll', function() {
            $('.profit_loss_totals').scrollLeft($(this).scrollLeft());
            const remainingScroll = $(this)[0].scrollWidth - $(this).outerWidth() - $(this).scrollLeft();
            const threshold = 25;
            if (remainingScroll <= threshold) {
                $('.total_revenue_td').removeClass('d-none')
            }
            else{
                $('.total_revenue_td').addClass('d-none')
            }
        });
        $('.profit_loss_totals').on('scroll', function() {
            $('[name="profit_loss_lines"] .table-responsive').scrollLeft($(this).scrollLeft());
        });
        $('[name="profit_loss_expense_lines"] .table-responsive').on('scroll', function() {
            $('.profit_loss_expense_totals').scrollLeft($(this).scrollLeft());
        });
        $('.profit_loss_expense_totals').on('scroll', function() {
            $('[name="profit_loss_expense_lines"] .table-responsive').scrollLeft($(this).scrollLeft());
        });
        $('[name="cash_flow_lines"] .table-responsive').on('scroll', function() {
            $('.cash_flow_totals').scrollLeft($(this).scrollLeft());
            $('.cash_flow_signing_block .table-responsive').scrollLeft($(this).scrollLeft());
        });
        $('.cash_flow_totals').on('scroll', function() {
            $('[name="cash_flow_lines"] .table-responsive').scrollLeft($(this).scrollLeft());
            $('.cash_flow_signing_block .table-responsive').scrollLeft($(this).scrollLeft());
        });
        $('.cash_flow_signing_block .table-responsive').on('scroll', function() {
            $('[name="cash_flow_lines"] .table-responsive').scrollLeft($(this).scrollLeft());
            $('.cash_flow_totals').scrollLeft($(this).scrollLeft());
        });
        $('[name="cash_flow_expense_lines"] .table-responsive').on('scroll', function() {
            $('.cash_flow_expense_totals').scrollLeft($(this).scrollLeft());
        });
        $('.cash_flow_expense_totals').on('scroll', function() {
            $('[name="cash_flow_expense_lines"] .table-responsive').scrollLeft($(this).scrollLeft());
        });
        $('[name="productivity_ratio_lines"] .table-responsive').on('scroll', function() {
            $('.productivity_ratio_totals').scrollLeft($(this).scrollLeft());
        });
        $('.productivity_ratio_totals').on('scroll', function() {
            $('[name="productivity_ratio_lines"] .table-responsive').scrollLeft($(this).scrollLeft());
        });

        $('[name="sales_forecast_lines"] table thead th').each(function(index, td){
            $($('.forecast_totals tbody tr:first td')[index]).css('width',$(td).css('width'))
            $($('.forecast_totals tbody tr:first td')[index]).css('min-width',$(td).css('width'))
            $($('.forecast_totals tbody tr:first td')[index]).css('max-width',$(td).css('width'))
        })
        $('[name="profit_loss_lines"] table thead th').each(function(index, td){
            $($('.profit_loss_totals tbody tr:first td')[index]).css('width',$(td).css('width'))
            $($('.profit_loss_totals tbody tr:first td')[index]).css('min-width',$(td).css('width'))
            $($('.profit_loss_totals tbody tr:first td')[index]).css('max-width',$(td).css('width'))
        })
        $('[name="profit_loss_expense_lines"] table thead th').each(function(index, td){
            $($('.profit_loss_expense_totals tbody tr:first td')[index]).css('width',$(td).css('width'))
            $($('.profit_loss_expense_totals tbody tr:first td')[index]).css('min-width',$(td).css('width'))
            $($('.profit_loss_expense_totals tbody tr:first td')[index]).css('max-width',$(td).css('width'))
        })
        $('[name="cash_flow_lines"] table thead th').each(function(index, td){
            $($('.cash_flow_totals tbody tr:first td')[index]).css('width',$(td).css('width'))
            $($('.cash_flow_totals tbody tr:first td')[index]).css('min-width',$(td).css('width'))
            $($('.cash_flow_totals tbody tr:first td')[index]).css('max-width',$(td).css('width'))
        })
        $('[name="cash_flow_expense_lines"] table thead th').each(function(index, td){
            $($('.cash_flow_expense_totals tbody tr:first td')[index]).css('width',$(td).css('width'))
            $($('.cash_flow_expense_totals tbody tr:first td')[index]).css('min-width',$(td).css('width'))
            $($('.cash_flow_expense_totals tbody tr:first td')[index]).css('max-width',$(td).css('width'))
        })
        $('[name="productivity_ratio_lines"] table thead th').each(function(index, td){
            $($('.productivity_ratio_totals tbody tr:first td')[index]).css('width',$(td).css('width'))
            $($('.productivity_ratio_totals tbody tr:first td')[index]).css('min-width',$(td).css('width'))
            $($('.productivity_ratio_totals tbody tr:first td')[index]).css('max-width',$(td).css('width'))
        })
    }
});
